alter table public.dating_profiles add column if not exists name text, add column if not exists age integer, add column if not exists vibe text, add column if not exists emoji text default '🐼', add column if not exists bio text, add column if not exists interests text[] not null default '{}', add column if not exists location text, add column if not exists country text, add column if not exists state_province text, add column if not exists gender text, add column if not exists relationship_goal text, add column if not exists looking_for text[] not null default '{}', add column if not exists about_traits text[] not null default '{}', add column if not exists lifestyle text[] not null default '{}', add column if not exists personality_tags text[] not null default '{}', add column if not exists love_language text, add column if not exists smoking text, add column if not exists drinking text, add column if not exists children text, add column if not exists education text, add column if not exists occupation text, add column if not exists intimacy_preference text, add column if not exists relationship_status text default 'single', add column if not exists height_cm integer, add column if not exists zodiac text, add column if not exists favorite_date text, add column if not exists photo_path text, add column if not exists blurred_photo_path text; alter table public.events add column if not exists ends_at timestamptz, add column if not exists category text, add column if not exists duration_minutes integer not null default 120, add column if not exists reach_scope text not null default 'worldwide', add column if not exists reach_country text, add column if not exists reach_state text, add column if not exists reach_city text, add column if not exists reach_area text, add column if not exists entry_fee_bc bigint not null default 0, add column if not exists entry_fee_amount numeric(12,2) not null default 0, add column if not exists entry_fee_currency text not null default 'N